      "id": "greeting::main",
      "identity": {
        "document": "greeting",
        "chunk": "main",
        "minor": null,
        "type": null
      },
      "name": "Main program",
      "body": "console.log(_\"format-greeting\");\n",
      "definitionPipeline": [],
